#!/usr/bin/env python3
"""Compare two benchmark JSON result files generated by scripts/bench/measure.py.
Computes per-process deltas for PSS, RSS, threads, and CPU usage.
Fails (exit 1) if kynex-shell PSS grows more than 3% or 2.0 MB unless --allow is provided.
Usage: scripts/bench/compare.py old.json new.json [--allow]
"""
import argparse, json, sys, os

def load_json(path):
    if not os.path.isfile(path):
        sys.exit(f"ERROR: File not found: {path}")
    with open(path) as f:
        try:
            return json.load(f)
        except Exception as e:
            sys.exit(f"ERROR: Failed to parse JSON from {path}: {e}")

def main():
    ap = argparse.ArgumentParser(description="Compare two benchmark JSON result files")
    ap.add_argument("old_json", help="Baseline benchmark JSON file")
    ap.add_argument("new_json", help="Comparison/new benchmark JSON file")
    ap.add_argument("--allow", action="store_true", help="Allow memory growth without failing exit code")
    ap.add_argument("--pss-pct-threshold", type=float, default=3.0, help="Max allowed shell PSS %% growth (default: 3.0)")
    ap.add_argument("--pss-mb-threshold", type=float, default=2.0, help="Max allowed shell PSS MB growth (default: 2.0)")
    args = ap.parse_args()

    old_data = load_json(args.old_json)
    new_data = load_json(args.new_json)

    old_procs = old_data.get("procs", {})
    new_procs = new_data.get("procs", {})

    all_proc_names = sorted(set(list(old_procs.keys()) + list(new_procs.keys())))
    if not all_proc_names:
        sys.exit("ERROR: No processes found in provided benchmark files.")

    print(f"\nComparing benchmarks:")
    print(f"  Old (baseline): {args.old_json} (SHA: {old_data.get('git_sha', 'unknown')}, profile: {old_data.get('build_profile', 'unknown')})")
    print(f"  New (current):  {args.new_json} (SHA: {new_data.get('git_sha', 'unknown')}, profile: {new_data.get('build_profile', 'unknown')})\n")

    hdr = f"{'Process':<16}{'Metric':<14}{'Old':>10}{'New':>10}{'Delta':>12}{'Delta %':>10}"
    print(hdr)
    print("-" * len(hdr))

    shell_growth_exceeded = False
    shell_delta_mb = 0.0
    shell_delta_pct = 0.0

    for proc in all_proc_names:
        o = old_procs.get(proc)
        n = new_procs.get(proc)

        if not o and not n:
            continue
        if not o:
            print(f"{proc:<16}{'PSS MB avg':<14}{'N/A':>10}{n['pss_mb_avg']:>10.1f}{'NEW':>12}{'':>10}")
            continue
        if not n:
            print(f"{proc:<16}{'PSS MB avg':<14}{o['pss_mb_avg']:>10.1f}{'N/A':>10}{'REMOVED':>12}{'':>10}")
            continue

        # PSS avg
        o_pss = o.get("pss_mb_avg", 0.0)
        n_pss = n.get("pss_mb_avg", 0.0)
        d_pss = n_pss - o_pss
        pct_pss = (d_pss / o_pss * 100.0) if o_pss > 0 else 0.0
        print(f"{proc:<16}{'PSS MB avg':<14}{o_pss:>10.1f}{n_pss:>10.1f}{d_pss:>+12.1f}{pct_pss:>+9.1f}%")

        # PSS max
        o_pss_max = o.get("pss_mb_max", 0.0)
        n_pss_max = n.get("pss_mb_max", 0.0)
        d_pss_max = n_pss_max - o_pss_max
        pct_pss_max = (d_pss_max / o_pss_max * 100.0) if o_pss_max > 0 else 0.0
        print(f"{'':<16}{'PSS MB max':<14}{o_pss_max:>10.1f}{n_pss_max:>10.1f}{d_pss_max:>+12.1f}{pct_pss_max:>+9.1f}%")

        # RSS avg
        o_rss = o.get("rss_mb_avg", 0.0)
        n_rss = n.get("rss_mb_avg", 0.0)
        d_rss = n_rss - o_rss
        pct_rss = (d_rss / o_rss * 100.0) if o_rss > 0 else 0.0
        print(f"{'':<16}{'RSS MB avg':<14}{o_rss:>10.1f}{n_rss:>10.1f}{d_rss:>+12.1f}{pct_rss:>+9.1f}%")

        # Threads
        o_th = o.get("threads", 0)
        n_th = n.get("threads", 0)
        d_th = n_th - o_th
        print(f"{'':<16}{'Threads':<14}{o_th:>10}{n_th:>10}{d_th:>+12}{'':>10}")

        # CPU %
        o_cpu = o.get("cpu_pct_avg", 0.0)
        n_cpu = n.get("cpu_pct_avg", 0.0)
        d_cpu = n_cpu - o_cpu
        print(f"{'':<16}{'CPU % avg':<14}{o_cpu:>10.2f}{n_cpu:>10.2f}{d_cpu:>+12.2f}{'':>10}")
        print("-" * len(hdr))

        if proc == "kynex-shell":
            shell_delta_mb = d_pss
            shell_delta_pct = pct_pss
            if d_pss > args.pss_mb_threshold or pct_pss > args.pss_pct_threshold:
                shell_growth_exceeded = True

    if shell_growth_exceeded:
        msg = (f"kynex-shell PSS grew by {shell_delta_mb:+.1f} MB ({shell_delta_pct:+.1f}%), "
               f"exceeding budget threshold (max +{args.pss_mb_threshold:.1f} MB or +{args.pss_pct_threshold:.1f}%)")
        if args.allow:
            print(f"\nWARNING: {msg} [ALLOWED via --allow]")
            sys.exit(0)
        else:
            print(f"\nFAIL: {msg}")
            print(f"To accept this growth, pass --allow and document rationale in docs/PERFORMANCE.md.")
            sys.exit(1)
    else:
        print(f"\nPASS: Memory delta for kynex-shell is within budget threshold (<= +{args.pss_mb_threshold:.1f} MB and <= +{args.pss_pct_threshold:.1f}%).")
        sys.exit(0)

if __name__ == "__main__":
    main()

